209 |     fn init_layout(&self) -> Result<PageInitialization> {
210 |         // Order must match `init_from_buffers`' consumption: scalar, rep, def.
211 |         Ok(PageInitialization::new([
212 |             self.layout.scalar.clone(),
213 |             self.layout.rep.clone(),
