26 | fn read_u32(buf: &[u8], offset: &mut usize) -> Result<u32> {
27 |     if *offset + 4 > buf.len() {
28 |         return Err(ArrowError::InvalidArgumentError(
29 |             "Invalid scalar value buffer: unexpected EOF".to_string(),
30 |         ));
31 |     }
32 |     let bytes = [
33 |         buf[*offset],
34 |         buf[*offset + 1],
35 |         buf[*offset + 2],
36 |         buf[*offset + 3],
37 |     ];
38 |     *offset += 4;
39 |     Ok(u32::from_le_bytes(bytes))
40 | }
