42 | fn read_bytes<'a>(buf: &'a [u8], offset: &mut usize, len: usize) -> Result<&'a [u8]> {
43 |     if *offset + len > buf.len() {
44 |         return Err(ArrowError::InvalidArgumentError(
45 |             "Invalid scalar value buffer: unexpected EOF".to_string(),
46 |         ));
47 |     }
48 |     let slice = &buf[*offset..*offset + len];
49 |     *offset += len;
50 |     Ok(slice)
51 | }
