61 | pub fn encode_scalar_value_buffer(scalar: &ArrayRef) -> Result<Vec<u8>> {
62 |     if scalar.len() != 1 || scalar.null_count() != 0 {
63 |         return Err(ArrowError::InvalidArgumentError(
64 |             "Scalar value buffer must be a single non-null value".to_string(),
65 |         ));
66 |     }
67 |     let data = scalar.to_data();
68 |     if data.offset() != 0 {
69 |         return Err(ArrowError::InvalidArgumentError(
70 |             "Scalar value buffer must have offset=0".to_string(),
71 |         ));
72 |     }
73 |     if !data.child_data().is_empty() {
74 |         return Err(ArrowError::InvalidArgumentError(
75 |             "Scalar value buffer does not support nested types".to_string(),
76 |         ));
77 |     }
78 | 
79 |     // Minimal format (RFC): store the Arrow value buffers for a length-1 array.
80 |     // Null bitmap and child data are intentionally not supported here.
81 |     //
82 |     // | u32 num_buffers |
83 |     // | u32 buffer_0_len | ... | u32 buffer_{n-1}_len |
84 |     // | buffer_0 bytes | ... | buffer_{n-1} bytes |
85 |     let mut out = Vec::with_capacity(128);
86 |     let buffers = data.buffers();
87 |     write_u32(&mut out, buffers.len() as u32);
88 |     for b in buffers {
89 |         write_u32(&mut out, b.len() as u32);
90 |     }
91 |     for b in buffers {
92 |         write_bytes(&mut out, b.as_slice());
93 |     }
94 |     Ok(out)
95 | }
