97 | pub fn decode_scalar_from_value_buffer(
98 |     data_type: &DataType,
99 |     value_buffer: &[u8],
100 | ) -> Result<ArrayRef> {
101 |     if matches!(
102 |         data_type,
103 |         DataType::Struct(_) | DataType::FixedSizeList(_, _)
104 |     ) {
105 |         return Err(ArrowError::InvalidArgumentError(format!(
106 |             "Scalar value buffer does not support nested data type {:?}",
107 |             data_type
108 |         )));
109 |     }
110 | 
111 |     let mut offset = 0;
112 |     let num_buffers = read_u32(value_buffer, &mut offset)? as usize;
113 |     let buffer_lens = (0..num_buffers)
114 |         .map(|_| read_u32(value_buffer, &mut offset).map(|l| l as usize))
115 |         .collect::<Result<Vec<_>>>()?;
116 | 
117 |     let mut buffers = Vec::with_capacity(num_buffers);
118 |     for len in buffer_lens {
119 |         let bytes = read_bytes(value_buffer, &mut offset, len)?;
120 |         buffers.push(Buffer::from_vec(bytes.to_vec()));
121 |     }
122 | 
123 |     if offset != value_buffer.len() {
124 |         return Err(ArrowError::InvalidArgumentError(
125 |             "Invalid scalar value buffer: trailing bytes".to_string(),
126 |         ));
127 |     }
128 | 
129 |     let mut builder = ArrayDataBuilder::new(data_type.clone())
130 |         .len(1)
131 |         .null_count(0);
132 |     for b in buffers {
133 |         builder = builder.add_buffer(b);
134 |     }
135 |     Ok(make_array(builder.build()?))
136 | }
