138 | pub fn decode_scalar_from_inline_value(
139 |     data_type: &DataType,
140 |     inline_value: &[u8],
141 | ) -> Result<ArrayRef> {
142 |     // I expect our input to be safe here, but I added some debug_assert_eq statements just in case.
143 |     // If they are triggered, we may need to change them to return actual errors.
144 |     //
145 |     // Boolean values are bit-packed in Arrow and therefore are not "fixed-stride" in bytes.
146 |     // As a result, `byte_width_opt()` returns `None` for `DataType::Boolean`, even though a
147 |     // length-1 scalar can be represented inline using a single byte (matching `try_inline_value`).
148 |     if matches!(data_type, DataType::Boolean) {
149 |         debug_assert_eq!(
150 |             inline_value.len(),
151 |             1,
152 |             "Invalid boolean inline scalar length (expected 1 byte, got {})",
153 |             inline_value.len()
154 |         );
155 |     } else if let Some(byte_width) = data_type.byte_width_opt() {
156 |         debug_assert_eq!(
157 |             inline_value.len(),
158 |             byte_width,
159 |             "Inline constant length mismatch for {:?}: expected {} bytes but got {}",
160 |             data_type,
161 |             byte_width,
162 |             inline_value.len()
163 |         );
164 |     }
165 | 
166 |     let data = ArrayDataBuilder::new(data_type.clone())
167 |         .len(1)
168 |         .null_count(0)
169 |         .add_buffer(Buffer::from_vec(inline_value.to_vec()))
170 |         .build()?;
171 |     Ok(make_array(data))
172 | }
