174 | pub fn try_inline_value(scalar: &ArrayRef) -> Option<Vec<u8>> {
175 |     if scalar.null_count() != 0 || scalar.len() != 1 {
176 |         return None;
177 |     }
178 |     let data = scalar.to_data();
179 |     if !data.child_data().is_empty() {
180 |         return None;
181 |     }
182 |     if data.buffers().len() != 1 {
183 |         return None;
184 |     }
185 |     let bytes = data.buffers()[0].as_slice();
186 |     if bytes.len() > INLINE_VALUE_MAX_BYTES {
187 |         return None;
188 |     }
189 |     Some(bytes.to_vec())
190 | }
